## 💻 5. JavaScript (`static/js/script.js`)

Usaremos **Chart.js** para os gráficos. Ele será carregado via CDN.

```js
import Chart from 'chart.js/auto';

// Estado global dos dados
let receitas = [];
let despesas = [];
let transferencias = [];

// Carrega dados ao iniciar
async function loadData() {
  try {
    const res = await fetch('/api/data');
    const data = await res.json();
    receitas = data.receitas || [];
    despesas = data.despesas || [];
    transferencias = data.transferencias || [];
    renderCharts();
    renderTables();
    updateKPIs();
  } catch (e) {
    console.error('Falha ao carregar dados:', e);
  }
}

function formatBrl(v) {
  return new Intl.NumberFormat('pt-BR', {
    style: 'currency', currency: 'BRL'
  }).format(v);
}

function formatData(iso) {
  if (!iso) return '-';
  const d = new Date(iso + 'T00:00:00');
  return d.toLocaleDateString('pt-BR');
}

function renderKPI(total, cor) {
  const change = total > 0 ? '+' : '';
  const cls = total >= 0 ? 'positivo' : 'negativo';
  return `<div class="kpi-value ${cls}" style="color:${cor}">${formatBrl(total)}</div>
         <div class="kpi-change ${cls}">${change} neste mês</div>`;
}

function renderCharts() {
  const ctxGeral = document.getElementById('graficoTotal').getContext('2d');
  const ctxPorCategoria = document.getElementById('graficoCat').getContext('2d');

  // Receitas por categoria
  const catReceitas = {};
  receitas.forEach(r => { catReceitas[r.Categoria] = (catReceitas[r.Categoria]||0)+r.Valor; });
  const labelsRC = Object.keys(catReceitas).sort();
  const valoresRC = labelsRC.map(k => catReceitas[k]);

  new Chart(ctxPorCategoria, {
    type: 'bar',
    data: {
      labels: labelsRC,
      datasets: [{
        label: 'Receitas por Categoria',
        data: valoresRC,
        backgroundColor: 'rgba(59,130,246,.5)',
        borderColor: 'rgba(59,130,246,1)',
        borderWidth: 1,
        borderRadius: 6
      }]
    },
    options: {
      responsive: true,
      plugins: { legend: { display: false } },
      scales: {
        y: { ticks: { color: '#8b8fa3' }, grid: { color: 'rgba(255,255,255,.06)' } },
        x: { ticks: { color: '#8b8fa3' } }
      }
    }
  });

  // Fluxo diário consolidado
  const dias = [];
  const vals = [];
  const map = { receita: 1, despesa: -1 };
  const setDias = new Set();
  [...receitas,...despesas].forEach(x => {
    const d = new Date(x.Data).toLocaleDateString('pt-BR', { month:'short', day:'numeric' });
    setDias.add(d);
    vals.push(map[x.Tipo]??1 * x.Valor);
  });
  const sorted = Array.from(setDias).sort();
  sorted.forEach((dt,i) => {
    dias.push(dt);
    const v = [...vals].filter(val => {
      const d = new Date(receitas.find(r=>r.Data===dt)?.Data || despesas.find(e=>e.Data===dt)?.Data);
      return d && d.toLocaleDateString() === dt;
    }).reduce((s,x)=> s+x,0);
    vals[i] = v;
  });

  new Chart(ctxGeral, {
    type: 'line',
    data: {
      labels: dias,
      datasets: [{
        label: 'Fluxo Diário',
        data: vals,
        borderColor: 'rgba(59,130,246,1)',
        backgroundColor: 'rgba(59,130,246,.15)',
        fill: true,
        tension: 0.35,
        pointRadius: 4,
        pointBackgroundColor: 'rgba(59,130,246,1)'
      }]
    },
    options: {
      responsive: true,
      plugins: { tooltip: { callbacks: { label: c => `${formatBrl(c.parsed.y)}` } } },
      scales: {
        y: { ticks: { color: '#8b8fa3' }, grid: { color: 'rgba(255,255,255,.06)' } },
        x: { ticks: { color: '#8b8fa3' } }
      }
    }
  });
}

function renderTables() {
  // Receitas
  const rcEl = document.getElementById('tabelaReceitas');
  if (!rcEl) return;
  let html = '<table class="data-table"><thead><tr>';
  html += ['ID','Categoria','Descrição','Data','Valor','Tipo'].map(h=>
    `<th>${h}</th>`
  ).join('');
  html += '</tr></thead><tbody>';
  receitas.sort((a,b)=> a.Data.localeCompare(b.Data)).forEach(r=>{
    html += `<tr>
      <td>${r.ID}</td>
      <td><span class="tag tag-receita">${r.Categoria}</span></td>
      <td>${r.Descricao}</td>
      <td>${formatData(r.Data)}</td>
      <td style="color:var(--accent-green)">${formatBrl(r.Valor)}</td>
      <td>${r.Remuneracao||'-'}</td>
      <td><button class="btn-delete" onclick="deleteRow(this,'receitas',${r.ID})">Excluir</button></td>
    </tr>`;
  });
  html += '</tbody></table>';
  rcEl.innerHTML = html;

  // Despesas
  const deEl = document.getElementById('tabelaDespesas');
  if (!deEl) return;
  let h = '<table class="data-table"><thead><tr>';
  h += ['ID','Categoria','Subcategoria','Descrição','Data','Valor','Tipo'].map(c=>`<th>${c}</th>`).join('');
  h += '</tr></thead><tbody>';
  despesas.sort((a,b)=> a.Data.localeCompare(b.Data)).forEach(d=>{
    h += `<tr>
      <td>${d.ID}</td>
      <td>${d.Categoria}</td>
      <td>${d.Subcategoria||'-'}</td>
      <td>${d.Descricao}</td>
      <td>${formatData(d.Data)}</td>
      <td style="color:var(--accent-red)">${formatBrl(d.Valor)}</td>
      <td>${d.Tipo}</td>
      <td><button class="btn-delete" onclick="deleteRow(this,'despesas',${d.ID})">Excluir</button></td>
    </tr>`;
  });
  h += '</tbody></table>';
  deEl.innerHTML = h;

  // Transferências
  const trEl = document.getElementById('tabelaTransferencias');
  if (!trEl) return;
  let t = '<table class="data-table"><thead><tr>';
  t += ['ID','De','Para','Data','Valor','Observação'].map(c=>`<th>${c}</th>`).join('');
  t += '</tr></thead><tbody>';
  transferencias.sort((a,b)=> a.Data.localeCompare(b.Data)).forEach(t2=>{
    t += `<tr>
      <td>${t2.ID}</td>
      <td>${t2.De}</td>
      <td>${t2.Para}</td>
      <td>${formatData(t2.Data)}</td>
      <td>${formatBrl(t2.Valor)}</td>
      <td>${t2.Observacao||'-'}</td>
      <td><button class="btn-delete" onclick="deleteRow(this,'transferencias',${t2.ID})">Excluir</button></td>
    </tr>`;
  });
  t += '</tbody></table>';
  trEl.innerHTML = t;
}

window.deleteRow = function(btn, tipo, id) {
  if (!confirm('Tem certeza que deseja excluir este registro?')) return;
  fetch(`/api/${tipo}/${id}`, { method: 'DELETE' })
    .then(r => r.ok ? reloadPage() : alert('Erro ao excluir'))
    .catch(() => alert('Falha na conexão'));
};

function reloadPage() {
  location.reload();
}

function updateKPIs() {
  const totReceitas = receitas.reduce((s,r)=> s+r.Valor,0);
  const totDespesas = despesas.reduce((s,d)=> s+d.Valor,0);
  const saldo = totReceitas - totDespesas;
  const retiradas = transferencias.filter(t=> t.De.includes('PF')).reduce((s,t)=> s+(t.Valor||0),0);
  const entradas = transferencias.filter(t=> t.De.includes('PJ')).reduce((s,t)=> s+(t.Valor||0),0);

  const kpis = [
    { title: '🟢 Total Recebido', value: totReceitas, cor: '#22c55e' },
    { title: '🔴 Total Despendido', value: totDespesas, cor: '#ef4444' },
    { title: '⚖️ Saldo Líquido', value: saldo, cor: saldo>=0?'#22c55e':'#ef4444' },
    { title: '🔄 Entradas Externas', value: entradas, cor: '#a855f7' },
    { title: '🚪 Retiradas Sócio', value: retiradas, cor: '#f59e0b' },
  ];

  const grid = document.getElementById('kpiGrid');
  if (!grid) return;
  grid.innerHTML = kpis.map(k => `
    <div class="kpi-card" style="border-top:3px solid ${k.cor}">
      <div class="kpi-label">${k.title}</div>
      ${renderKPI(k.value, k.cor)}
    </div>
  `).join('');
}

// Inicializa tudo
document.addEventListener('DOMContentLoaded', async () => {
  await loadData();
});
```

