window.openForm = function(tipo) {
  const el = document.getElementById(`form${tipo.charAt(0).toUpperCase() + tipo.slice(1)}`);
  if (!el) return;
  // Preenche IDs sequenciais
  const ids = el.querySelectorAll(':first-child[name=id]');
  const next = parseInt(ids[0]?.value||0) + 1 || 1;
  ids[0].value = next;
  el.querySelector('form').reset();
  el.querySelector('form').focus();
  el.style.display = 'grid';
};

window.addEvent = async function(tipo, form) {
  const fd = new FormData(form);
  try {
    const res = await fetch(`/api/${tipo}`, {
      method: 'POST',
      body: fd
    });
    if (res.ok) {
      showToast('✅ Registro adicionado com sucesso!');
      form.reset();
      setTimeout(reloadPage, 600);
    } else {
      const err = await res.text();
      showToast('❌ ' + err, 'alerta-erro');
    }
  } catch (e) {
    showToast('❌ Erro de conexão!', 'alerta-erro');
  }
};

function showToast(msg, cls='alerta-sucesso') {
  const el = document.getElementById(cls === 'alerta-sucesso' ? 'toastSucesso' : 'toastErro');
  el.textContent = msg;
  el.className = `toast ${cls} show`;
  setTimeout(() => el.classList.remove('show'), 3000);
}

// Navegação entre abas mantendo estado
document.getElementById('navTabs').addEventListener('click', btn => {
