  btn.classList.add('active');
  const tab = btn.dataset.tab;
  document.getElementById(`tab${tab.charAt(0).toUpperCase()+tab.slice(1)}`).scrollIntoView({ behavior:'smooth' });
  // Recarrega dados da aba selecionada
  fetch(`/api/data?tab=${tab}`)
    .then(r=>r.json())
    .then(data=>{
      window.receitas = data.receitas||[];
      window.despesas = data.despesas||[];
      window.transferencias = data.transferencias||[];
      renderCharts(); renderTables(); updateKPIs();
    });
});

function unique_categories(tipo) {
  const arr = window[tipo];
  if (!arr) return [];
  const cats = new Set(arr.map(r=> r.Categoria || r.categoria || ''));
  return Array.from(cats).sort();
