## 🐍 7. Aplicação FastHTML (`app.py`)

Este é o coração do sistema — API REST + template Jinja2 + sincronização com CSV.

```python
import os
import csv
import json
import uuid
from datetime import datetime
from pathlib import Path

from fasthtml import App, Route, Response
from fasthtml.responses import JSONResponse
import pandas as pd

BASE = Path(__file__).parent
DATA_DIR = BASE / "data"
DATA_DIR.mkdir(exist_ok=True)

# ------------------------------------------------------------------
# Helpers de I/O com CSV
# ------------------------------------------------------------------
def load_csv(table: str) -> list[dict]:
    """Carrega tabela do CSV correspondente."""
    path = DATA_DIR / f"{table}.csv"
    if not path.exists():
        return []
    df = pd.read_csv(path, dtype=str)
    # Normaliza colunas
    cols = {c.strip().lower().replace(' ','_'): c for c in df.columns}
    rows = []
    for _, r in df.iterrows():
        row = {}
        for key, orig in cols.items():
            val = r.get(key, "")
            # Torna numérico quando possível
            try:
                if any(k in orig for k in ("valor", "data")):
                    val = float(val) if pd.notna(val) else ""
                elif key == "id":
                    val = int(val) if val.isdigit() else ""
            except (ValueError, TypeError):
                pass
            row[orig] = str(val) if isinstance(val, str) else val
        rows.append(row)
    return rows

def save_csv(table: str, records: list[dict]):
    """Grava lista de dicts no CSV."""
    path = DATA_DIR / f"{table}.csv"
    if not records:
        path.write_text("")
        return
    # Descobre colunas únicas
    all_cols = set()
    for rec in records:
        all_cols.update(rec.keys())
    df = pd.DataFrame(records)
    # Renomeia para nomes amigáveis
    mapping = {
        "id":"ID",
        "categoria":"Categoria",
        "descricao":"Descrição",
        "data":"Data",
        "valor":"Valor",
        "remuneracao":"Remuneração",
        "subcategoria":"Subcategoria",
        "tipo":"Tipo",
        "de":"De",
        "para":"Para",
        "observacao":"Observação",
    }
    new_cols = []
    for c in all_cols:
        m = mapping.get(c, c.title().replace("_"," "))
        new_cols.append(m)
    df = df[new_cols]
    # Garante tipos corretos
    for col in ["Valor", "Data"]:
        if col in df.columns:
            df[col] = pd.to_datetime(df[col], errors="coerce").dt.strftime("%Y-%m-%d") if col=="Data" else pd.to_numeric(df[col], errors="coerce")
    df.to_csv(path, index=False)

def next_id(table: str) -> int:
    """Gera próximo ID sequencial."""
    csv_path = DATA_DIR / f"{table}.csv"
    if not csv_path.exists():
        return 1
    df = pd.read_csv(csv_path)
    if "ID" not in df.columns:
        return 1
    ids = pd.to_numeric(df["ID"], errors="coerce").dropna().astype(int).max() or 0
    return int(ids) + 1


# ------------------------------------------------------------------
# Rotas
# ------------------------------------------------------------------
app = App()

@app.get("/api/data")
async def get_all_data():
    """Retorna todos os dados agregados."""
    tab = request.query_params.get("tab", "geral")
    data = {
        "receitas": load_csv("receitas"),
        "despesas": load_csv("despesas"),
        "transferencias": load_csv("transferencias"),
    }
    if tab == "geral":
        # Agregações
        tot_rec = sum(float(r["Valor"]) for r in data["receitas"] if r.get("Valor","").strip())
        tot_desp = sum(float(d["Valor"]) for d in data["despesas"] if d.get("Valor","").strip())
        saldo = tot_rec - tot_desp
        transfers_in = sum(float(t["Valor"]) for t in data["transferencias"]
                           if t.get("De","").lower().startswith("pj"))
        transfers_out = sum(float(t["Valor"]) for t in data["transferencias"]
                            if t.get("De","").lower().startswith("pf"))
        data["agregado"] = {
            "total_receitas": tot_rec,
            "total_despesas": tot_desp,
            "saldo": saldo,
            "entradas_externas": transfers_in,
            "retiradas_socio": transfers_out,
        }
    return JSONResponse(data)


@app.get("/api/{tipo}")
async def list_table(tipo: str):
    """Lista registros de uma tabela (suporta query params básicos)."""
    table_map = {"receitas":"receitas","despesas":"despesas","transferencias":"transferencias"}
    tbl = table_map.get(tipo, tipo)
    records = load_csv(tbl)
    # Filtro simples por data/categoria
    q = request.query_params
    date_f = q.get("desde") or q.get("date_from")
    to_date = q.get("ate") or q.get("date_to")
    cat = q.get("categoria")
    if date_f:
        try:
            start = datetime.strptime(date_f, "%Y-%m-%d").date()
            records = [r for r in records if r.get("Data","").startswith(str(start))]
        except ValueError:
            pass
    if cat and tbl != "transferencias":
        cat_l = cat.lower()
        records = [r for r in records if cat_l in r.get("Categoria","").lower()]
    return JSONResponse({""+tbl+":": records})


@app.post("/api/{tipo}")
async def create_record(tipo: str, files=None, form=None):
    """Inseri um novo registro via formulário multipart ou JSON."""
    table_map = {"receitas":"receitas","despesas":"despesas","transferencias":"transferencias"}
    tbl = table_map.get(tipo, tipo)
    id_next = next_id(tbl)
    record = {}

    # Parseia corpo
    if files:
        # Multipart: procura campos por nome
        for part in files:
            name = part.name.split(";")[0].strip().lower()
            clean = next((k for k in ["id","categoria","descricao","data","valor","remuneracao",
                                       "subcategoria","tipo","de","para","observacao",
                                       "id","categoria","data","valor"] if k in name), None)
            if clean:
                record[clean] = part.content.decode("utf-8", errors="ignore")
    if form:
        for k, v in form.items():
            if v is not None and str(v).strip():
                record[k.lower()] = str(v)

    # Preenche defaults
    if "id" not in record:
        record["id"] = str(id_next)
    if "data" not in record:
        record["data"] = datetime.now().strftime("%Y-%m-%d")
    if "valor" not in record:
        try:
            record["valor"] = float(record.get("valor", 0))
        except (ValueError, TypeError):
            record["valor"] = 0.0

    save_csv(tbl, [record])
    return JSONResponse({"status":"ok","id":record.get("id")})


@app.delete("/api/{tipo}/{id}")
async def delete_record(tipo: str, id: str):
    """Remove um registro pelo ID."""
    table_map = {"receitas":"receitas","despesas":"despesas","transferencias":"transferencias"}
    tbl = table_map.get(tipo, tipo)
    path = DATA_DIR / f"{tbl}.csv"
    if not path.exists():
        return JSONResponse({"error":"tabela não encontrada"}, status=404)
    try:
        df = pd.read_csv(path)
        mask = df["ID"].astype(str) == str(id)
        if not mask.any():
            return JSONResponse({"error":"ID não encontrado"}, status=404)
        df = df[~mask]
        df.to_csv(path, index=False)
        return JSONResponse({"status":"ok"})
    except Exception as e:
        return JSONResponse({"error": str(e)}, status=500)


# ------------------------------------------------------------------
# Renderização da página
# ------------------------------------------------------------------
@app.get("/")
async def index():
    """Template Jinja2."""
    receitas = load_csv("receitas")
    despesas = load_csv("despesas")
    transf = load_csv("transferencias")
    # Categorias únicas
    cats_r = sorted(set(r.get("Categoria","") for r in receitas if r.get("Categoria")))
    cats_d = sorted(set(d.get("Categoria","") for d in despesas if d.get("Categoria")))
    all_cats = sorted(set(cats_r + cats_d))

    return TemplateResponse("index.html", context={
        "receitas": receitas,
        "despesas": despesas,
        "transferencias": transf,
        "unique_categories_receitas": cats_r,
        "unique_categories_despesas": cats_d,
    })


# ------------------------------------------------------------------
# Servidor
# ------------------------------------------------------------------
if __name__ == "__main__":
    print("🚀 Servidor CaixFlow rodando em http://localhost:8000")
    app.run(host="0.0.0.0", port=8000, debug=True)
```

