  --text-muted: #8b8fa3;
  --accent-blue: #3b82f6;
  --accent-green: #22c55e;
  --accent-red: #ef4444;
  --accent-purple: #a855f7;
  --accent-orange: #f59e0b;
  --radius: 12px;
  --shadow: 0 4px 24px rgba(0,0,0,.4);
  --font: 'Inter', system-ui, -apple-system, sans-serif;
}

body {
  font-family: var(--font);
  background: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.6;
  min-height: 100vh;
}

a { color: var(--accent-blue); text-decoration: none; }
a:hover { text-decoration: underline; }

/* ===== LAYOUT ===== */
.dashboard-container {
  max-width: 1280px;
  margin: 0 auto;
  padding: 2rem 1.5rem;
}

header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 2.5rem;
  padding-bottom: 1.5rem;
  border-bottom: 1px solid var(--border);
}

.logo {
  display: flex;
  align-items: center;
  gap: .8rem;
  font-size: 1.4rem;
  font-weight: 700;
  letter-spacing: -.02em;
}

.logo-icon {
  width: 36px; height: 36px;
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
  border-radius: 8px;
  display: flex; align-items: center; justify-content: center;
  font-weight: 800; color: #fff;
}

nav button {
  background: transparent;
  border: 1px solid var(--border);
  color: var(--text-muted);
  padding: .6rem 1.2rem;
  border-radius: var(--radius);
  cursor: pointer;
  font-size: .9rem;
  transition: all .2s ease;
  margin-right: .5rem;
}

nav button:hover, nav button.active {
  background: var(--accent-blue);
  color: #fff;
  border-color: var(--accent-blue);
}

/* ===== CARDS DE KPI ===== */
.kpi-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1.5rem;
  margin-bottom: 2.5rem;
}

.kpi-card {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.8rem;
  position: relative;
  overflow: hidden;
  transition: transform .2s ease, box-shadow .2s ease;
}

.kpi-card:hover {
  transform: translateY(-2px);
  box-shadow: var(--shadow);
}

.kpi-card::before {
  content: '';
  position: absolute;
  top: 0; left: 0;
  width: 100%; height: 3px;
  border-radius: var(--radius) var(--radius) 0 0;
}

.kpi-label {
  font-size: .8rem;
  color: var(--text-muted);
  text-transform: uppercase;
  letter-spacing: .08em;
  margin-bottom: .5rem;
}

.kpi-value {
  font-size: 2rem;
  font-weight: 700;
  line-height: 1.2;
}

.kpi-change {
  font-size: .85rem;
  margin-top: .4rem;
  display: flex;
  align-items: center;
  gap: .3rem;
}

.positivo { color: var(--accent-green); }
.negativo { color: var(--accent-red); }

/* ===== SEÇÕES DE TABELAS ===== */
.tab-section {
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.8rem;
  margin-bottom: 2rem;
}

.tab-header {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 1.2rem;
  flex-wrap: wrap;
  gap: .8rem;
}

.tab-title {
  font-size: 1.1rem;
  font-weight: 600;
}

.filter-group {
  display: flex;
  align-items: center;
  gap: .6rem;
  flex-wrap: wrap;
}

.filter-group select,
.filter-group input {
  background: var(--bg-input);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: .5rem .8rem;
  border-radius: var(--radius);
  font-size: .85rem;
  outline: none;
  width: 200px;
}

.filter-group select:focus,
.filter-group input:focus {
  border-color: var(--accent-blue);
}

.add-btn {
  background: linear-gradient(135deg, var(--accent-blue), var(--accent-purple));
  color: #fff;
  border: none;
  padding: .5rem 1rem;
  border-radius: var(--radius);
  font-size: .85rem;
  cursor: pointer;
  font-weight: 600;
  transition: opacity .2s;
}

.add-btn:hover { opacity: .9; }
.add-btn:active { transform: scale(.98); }

/* ===== TABELA MODERNA ===== */
.data-table {
  width: 100%;
  border-collapse: collapse;
  font-size: .9rem;
}

.data-table th {
  text-align: left;
  padding: .8rem 1rem;
  color: var(--text-muted);
  font-weight: 600;
  border-bottom: 2px solid var(--border);
  white-space: nowrap;
}

.data-table td {
  padding: .8rem 1rem;
  border-bottom: 1px solid rgba(45,49,68,.3);
}

.data-table tr:last-child td { border-bottom: none; }
.data-table tr:hover { background: rgba(59,130,246,.06); }

.tag {
  display: inline-block;
  padding: .2rem .6rem;
  border-radius: 99px;
  font-size: .75rem;
  font-weight: 600;
}

.tag-receita { background: rgba(34,197,94,.15); color: var(--accent-green); }
.tag-despesa { background: rgba(239,68,68,.15); color: var(--accent-red); }
.tag-transferencia { background: rgba(168,85,247,.15); color: var(--accent-purple); }
.tag-investimento { background: rgba(245,158,11,.15); color: var(--accent-orange); }

.btn-delete {
  background: transparent;
  color: var(--accent-red);
  border: 1px solid rgba(239,68,68,.3);
  border-radius: 6px;
  padding: .2rem .5rem;
  font-size: .75rem;
  cursor: pointer;
  transition: all .2s;
}

.btn-delete:hover {
  background: rgba(239,68,68,.1);
  color: #fff;
}

/* ===== FORMULÁRIO ADICIONAR ===== */
.form-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(240px, 1fr));
  gap: 1rem;
  margin-top: 1rem;
}

.form-card {
  background: var(--bg-input);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.2rem;
}

.form-card label {
  display: block;
  font-size: .8rem;
  color: var(--text-muted);
  margin-bottom: .35rem;
  font-weight: 600;
}

.form-card input,
.form-card select,
.form-card textarea {
  width: 100%;
  background: var(--bg-primary);
  border: 1px solid var(--border);
  color: var(--text-main);
  padding: .6rem .8rem;
  border-radius: 8px;
  font-size: .9rem;
  outline: none;
  transition: border-color .2s;
}

.form-card input:focus,
.form-card select:focus,
.form-card textarea:focus {
  border-color: var(--accent-blue);
}

/* ===== CHART ===== */
.chart-container {
  margin-top: 1.5rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius);
  padding: 1.5rem;
}

/* ===== TOAST / ALERTA ===== */
.toast {
  position: fixed;
  bottom: 2rem;
  right: 2rem;
  background: var(--accent-green);
  color: #fff;
  padding: .8rem 1.5rem;
  border-radius: var(--radius);
  box-shadow: var(--shadow);
  transform: translateY(100px);
  transition: transform .3s ease;
  z-index: 999;
  font-weight: 500;
}

.toast.show { transform: translateY(0); }

.alerta-sucesso { background: var(--accent-green); }
.alerta-erro { background: var(--accent-red); }

/* ===== RESPONSIVO ===== */
@media (max-width: 768px) {
  .kpi-grid { grid-template-columns: 1fr 1fr; }
  .form-grid { grid-template-columns: 1fr; }
  header { flex-direction: column; gap: 1rem; }
  nav button { width: 100%; text-align: center; }
  .dashboard-container { padding: 1rem; }
  .tab-header { flex-direction: column; }
  .filter-group { width: 100%; }
  .filter-group select, .filter-group input { width: 100%; }
}

@media (max-width: 480px) {
  .kpi-grid { grid-template-columns: 1fr; }
  .kpi-value { font-size: 1.5rem; }
}
```

